def oracle(input):
    n = input['n']
    f = input['f']
    indeg = [0] * n
    for v in f:
        indeg[v - 1] += 1
    roots = []
    for i in range(n):
        if indeg[i] == 0:
            roots.append(i + 1)
    if roots:
        return {'possible': False}
    seen = [0] * n
    reps = []
    for i in range(1, n + 1):
        if seen[i - 1]:
            continue
        cur = i
        pos = {}
        path = []
        while not seen[cur - 1] and cur not in pos:
            pos[cur] = len(path)
            path.append(cur)
            cur = f[cur - 1]
        if not seen[cur - 1]:
            cyc = path[pos[cur]:]
            if len(cyc) != 1:
                return {'possible': False}
            reps.append(cur)
        for x in path:
            seen[x - 1] = 1
    reps.sort()
    m = len(reps)
    rep_to_idx = {}
    for i in range(m):
        rep_to_idx[reps[i]] = i + 1
    g = [0] * n
    for i in range(1, n + 1):
        cur = i
        while f[cur - 1] != cur:
            cur = f[cur - 1]
        g[i - 1] = rep_to_idx[cur]
    h = reps[:]
    return {'possible': True, 'm': m, 'g': g, 'h': h}

