    B = input['B']
    sa = {}
    sb = {}
    i = 0
    while i < n:
        sa[A[i]] = True
        i += 1
    i = 0
    while i < m:
        sb[B[i]] = True
        i += 1
    i = 0
    while i < n:
        j = 0
        while j < m:
            s = A[i] + B[j]
            if (s not in sa) and (s not in sb):
                return [A[i], B[j]]
            j += 1
        i += 1
    return None

